:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
}
body {
  margin: 0;
  background: #faf9f6;
  color: #1c2524;
}
.site-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem 1rem;
  margin: 0 auto;
  max-width: 64rem;
  padding: 2rem 2rem 0;
}
.site-name {
  color: inherit;
  font-weight: 700;
  text-decoration: none;
}
.site-tagline {
  margin: 0;
  opacity: 0.75;
}
main {
  margin: 10vh auto;
  max-width: 64rem;
  padding: 2rem;
}
.eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* Gallery: an adaptive grid; the focal point positions each cropped image. */
:where([data-lace-block="gallery"]) [data-lace-part="items"] {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fill, minmax(min(14rem, 100%), 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
}
:where([data-lace-block="gallery"]) figure {
  margin: 0;
}
:where([data-lace-block="gallery"]) [data-lace-part="media"] {
  aspect-ratio: 4 / 3;
  display: block;
  height: auto;
  object-fit: cover;
  width: 100%;
}

/* Lightbox: the image opens the original full screen in a native dialog. */
:where([data-lace-part="lightbox-trigger"]) {
  background: none;
  border: 0;
  cursor: zoom-in;
  display: block;
  padding: 0;
  width: 100%;
}
:where([data-lace-part="lightbox-trigger"]):focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
:where([data-lace-part="lightbox-trigger"]) img {
  display: block;
  height: auto;
  max-width: 100%;
}
/* A linked image (image block or gallery item) opens its link instead of the lightbox. */
:where([data-lace-part="link"]) {
  display: block;
}
:where([data-lace-part="link"]):focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
:where([data-lace-part="lightbox"]) {
  background: transparent;
  border: 0;
  max-height: 100dvh;
  max-width: 100vw;
  padding: 0;
}
:where([data-lace-part="lightbox"])::backdrop {
  background: rgb(0 0 0 / 0.85);
}
:where([data-lace-part="lightbox-media"]) {
  display: block;
  height: auto;
  max-height: 100dvh;
  max-width: 100vw;
  object-fit: contain;
  width: auto;
}
:where([data-lace-part="lightbox-close"]) {
  background: #faf9f6;
  border: 0;
  border-radius: 999px;
  color: #1c2524;
  cursor: pointer;
  font: inherit;
  padding: 0.5rem 1rem;
  position: fixed;
  right: 1rem;
  top: 1rem;
}

/* Navigation: a vertical list on narrow screens, a row with dropdowns from 48rem. */
:where([data-lace-block="navigation"], .site-nav) ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
:where([data-lace-block="navigation"]) [data-lace-part="list"],
:where(.site-nav) > ul {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
:where([data-lace-block="navigation"]) a,
:where([data-lace-block="navigation"]) summary {
  overflow-wrap: anywhere;
}
:where([data-lace-block="navigation"]) [data-lace-part="toggle"] {
  cursor: pointer;
}
:where([data-lace-block="navigation"]) [data-lace-part="children"] {
  display: grid;
  gap: 0.25rem;
  margin-block-start: 0.5rem;
  padding-inline-start: 1rem;
}
:where([data-lace-block="navigation"]) [aria-current="page"] {
  font-weight: 700;
}
.site-header > nav {
  flex-basis: 100%;
}
@media (min-width: 48rem) {
  :where([data-lace-block="navigation"]) [data-lace-part="list"],
  :where(.site-nav) > ul {
    flex-flow: row wrap;
    gap: 0.5rem 1.5rem;
  }
  :where([data-lace-block="navigation"]) [data-lace-part="submenu"] {
    position: relative;
  }
  :where([data-lace-block="navigation"]) [data-lace-part="children"] {
    background: Canvas;
    border: 1px solid;
    inset-block-start: 100%;
    inset-inline-start: 0;
    min-width: 12rem;
    padding: 0.75rem;
    position: absolute;
    z-index: 1;
  }
  .site-header > nav {
    flex-basis: auto;
    margin-inline-start: auto;
  }
}
